import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET = os.environ.get('HMAC_SECRET', 'default-secret-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        role TEXT DEFAULT 'user',
        password_hash TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        query TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_api_key(req):
    """Verify HMAC-based API key from X-Api-Signature header"""
    payload = req.get_data(as_text=True)
    signature = req.headers.get('X-Api-Signature', '')
    expected = hmac.new(SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(signature, expected)

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')

    # Whitelist allowed search fields
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Build query - field is validated above, value is user-controlled
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    db = get_db()
    try:
        # Log the search for audit purposes
        db.execute("INSERT INTO audit_log (action, query) VALUES (?, ?)", 
                   ('search', query))
        db.commit()

        results = db.execute(query).fetchall()
        return jsonify([dict(row) for row in results])
    except Exception as e:
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user profile by ID"""
    db = get_db()
    user = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', 
                      (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user account"""
    data = request.get_json()
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    password = data.get('password', '')
    pw_hash = hashlib.sha256(password.encode()).hexdigest()

    db = get_db()
    try:
        db.execute('INSERT INTO users (username, email, password_hash) VALUES (?, ?, ?)',
                   (data['username'], data['email'], pw_hash))
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username exists'}), 409

@app.route('/api/admin/export', methods=['GET'])
def export_data():
    """Admin endpoint - exports all user data including password hashes"""
    if not verify_api_key(request):
        return jsonify({'error': 'Unauthorized'}), 403
    db = get_db()
    users = db.execute('SELECT * FROM users').fetchall()
    return jsonify([dict(row) for row in users])

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
